vec3 finish(vec3 c){return 1.0-exp(-max(c,vec3(0.0)));}
float twoCos(float b){float b2=b*b;return 2.0-b2*(1.0-b2*(1.0/12.0-b2*(1.0/360.0-b2/20160.0)));}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 p=(2.0*fragCoord-iResolution.xy)/min(iResolution.x,iResolution.y);
 float t=vrchPhase_speed(),hit=smoothstep(.0,.75,uParam_accent);
 float spin=.15*sin(t*.2);
 p=mat2(cos(spin),-sin(spin),sin(spin),cos(spin))*p;vec3 c=vec3(.001,.003,.009);
 // Layer i: depth=.6+1.8i/27. Every wave phase advances by a fixed step per layer,
 // so each sine follows s[i+1]=2cos(step)s[i]-s[i-1]: two instructions per layer.
 // 2cos(b) from its series: the recurrence amplifies any error in it, so avoid the approximate cosine.
 float kx=p.x/uParam_spread,dx=kx*1.8/27.0,x0=kx*.6;
 float a1=x0*1.5+t*.42,b1=dx*1.5+3.8/27.0,s1=sin(a1),q1=sin(a1-b1),m1=twoCos(b1);
 float a2=x0*2.7-t*.3,b2=dx*2.7+4.0/27.0,s2=sin(a2),q2=sin(a2-b2),m2=twoCos(b2);
 float a3=x0*3.1+t*.45,b3=dx*3.1+7.0/27.0,s3=sin(a3),q3=sin(a3-b3),m3=twoCos(b3);
 float a4=x0*5.8-t*.65,b4=dx*5.8,s4=sin(a4),q4=sin(a4-b4),m4=twoCos(b4);
 float a5=x0*1.5-t*.7,b5=dx*1.5+10.0/27.0,s5=sin(a5),q5=sin(a5-b5),m5=twoCos(b5);
 float sweepX=1.4*sin(t*.47);
 bool accent=hit>0.0;
 float spanY=1.0+uParam_mass*2.6;
 float y=p.y*.6,dy=p.y*1.8/27.0,center0=-.5*spanY,dCenter=spanY/27.0;
 float width=.004+uParam_ridges*.009,fall=12.0-uParam_mass*6.0,sharp=90.0/width;
 // sin(pi*layer) and the depth weight also advance by fixed steps.
 float arch=0.0,archPrev=-sin(3.14/27.0),depthWeight=.35;
 // Colour is linear in the layer and in its warmth weight: accumulate scalar
 // weights and assemble once. hue=cool+(warm-cool)*s, cool=C0+layer*dC, warm=W0+layer*dW.
 float sK=0.0,sKL=0.0,sKW=0.0,sKWL=0.0,sA=0.0;
// Two layers per iteration: the recurrences alternate which variable holds the newer value, so no copies are needed.
 float yc=y-center0,dyc=dy-dCenter,dw=depthWeight,layer=0.0;
 float u0=(x0-sweepX)*1.2,du=dx*1.2;
 if(accent){
  float sweep=exp(-u0*u0),sweepStep=exp(-du*(2.0*u0+du)),sweepCurve=exp(-2.0*du*du);
  float crestS=sin(-t*.55),crestPrev=sin(-t*.55-11.0/27.0);
  for(int i=0;i<14;i++){
   {float d=abs(yc-(.36*s1+.22*s2+uParam_bend*(s3+.38*s4)));
    float filament=1.0/(d*d*sharp+1.0);
    float k=(filament*(.1265+.1035*s5)+exp(-d*fall)*.065)*dw;
    float crest=.5+.5*crestS;crest*=crest*crest;float a=filament*hit*sweep*(.2+.8*crest)*.42;k+=.7*a;sA+=a;
    sweep*=sweepStep;sweepStep*=sweepCurve;crestPrev=1.83630234*crestS-crestPrev;
    float kw=k*(.35+.65*arch);sK+=k;sKL+=k*layer;sKW+=kw;sKWL+=kw*layer;
    q1=m1*s1-q1;q2=m2*s2-q2;q3=m3*s3-q3;q4=m4*s4-q4;q5=m5*s5-q5;
    archPrev=1.98649041*arch-archPrev;yc+=dyc;dw+=.65/27.0;layer+=1.0/27.0;}
   {float d=abs(yc-(.36*q1+.22*q2+uParam_bend*(q3+.38*q4)));
    float filament=1.0/(d*d*sharp+1.0);
    float k=(filament*(.1265+.1035*q5)+exp(-d*fall)*.065)*dw;
    float crest=.5+.5*crestPrev;crest*=crest*crest;float a=filament*hit*sweep*(.2+.8*crest)*.42;k+=.7*a;sA+=a;
    sweep*=sweepStep;sweepStep*=sweepCurve;crestS=1.83630234*crestPrev-crestS;
    float kw=k*(.35+.65*archPrev);sK+=k;sKL+=k*layer;sKW+=kw;sKWL+=kw*layer;
    s1=m1*q1-s1;s2=m2*q2-s2;s3=m3*q3-s3;s4=m4*q4-s4;s5=m5*q5-s5;
    arch=1.98649041*archPrev-arch;yc+=dyc;dw+=.65/27.0;layer+=1.0/27.0;}
  }
 }else{
  for(int i=0;i<14;i++){
   {float d=abs(yc-(.36*s1+.22*s2+uParam_bend*(s3+.38*s4)));
    float filament=1.0/(d*d*sharp+1.0);
    float k=(filament*(.1265+.1035*s5)+exp(-d*fall)*.065)*dw;
    float kw=k*(.35+.65*arch);sK+=k;sKL+=k*layer;sKW+=kw;sKWL+=kw*layer;
    q1=m1*s1-q1;q2=m2*s2-q2;q3=m3*s3-q3;q4=m4*s4-q4;q5=m5*s5-q5;
    archPrev=1.98649041*arch-archPrev;yc+=dyc;dw+=.65/27.0;layer+=1.0/27.0;}
   {float d=abs(yc-(.36*q1+.22*q2+uParam_bend*(q3+.38*q4)));
    float filament=1.0/(d*d*sharp+1.0);
    float k=(filament*(.1265+.1035*q5)+exp(-d*fall)*.065)*dw;
    float kw=k*(.35+.65*archPrev);sK+=k;sKL+=k*layer;sKW+=kw;sKWL+=kw*layer;
    s1=m1*q1-s1;s2=m2*q2-s2;s3=m3*q3-s3;s4=m4*q4-s4;s5=m5*q5-s5;
    arch=1.98649041*archPrev-arch;yc+=dyc;dw+=.65/27.0;layer+=1.0/27.0;}
  }
 }
 float sKS=uParam_warmth*sKW,sKSL=uParam_warmth*sKWL;
 const vec3 C0=vec3(.015,.15,.65),dC=vec3(0.0,.80,.02),W0=vec3(.65,.025,.38),dW=vec3(.35,.415,-.325);
 c+=C0*sK+dC*sKL+(W0-C0)*sKS+(dW-dC)*sKSL+vec3(.8,.94,1.0)*(.3*sA);
 fragColor=vec4(finish(c*(.6+uParam_light*1.6)),1.0);
}
